def pw(gname; v): if v != "" and v != null then if has("userGroups") then .userGroups |= map(if .name == gname then .password = v else . end) else . end else . end;

if . == {} then 
  {
    "name": "${serverName}",
    "queryPort": ${queryPort},
    "slotCount": ${slotCount},
    "gameSettingsPreset": "${gameSettingsPreset}",
    "enableVoiceChat": ${enableVoiceChat},
    "enableTextChat": ${enableTextChat},
    "userGroups": [
      {"name": "Admin", "password": "${adminPassword}"},
      {"name": "Friend", "password": "${friendPassword}"},
      {"name": "Guest", "password": "${guestPassword}"},
      {"name": "Visitor", "password": "${visitorPassword}"}
    ]
  }
else
  .name = "${serverName}"
  | .queryPort = ${queryPort}
  | .slotCount = ${slotCount}
  | .enableVoiceChat = ${enableVoiceChat}
  | .enableTextChat = ${enableTextChat}
  | .gameSettingsPreset = "${gameSettingsPreset}"
  | pw("Admin", "${adminPassword}")
  | pw("Friend", "${friendPassword}")
  | pw("Guest", "${guestPassword}")
  | pw("Visitor", "${visitorPassword}")
  | if ([.userGroups[].password | select(. != "")] | length) == ([.userGroups[].password | select(. != "")] | unique | length) then . else error("Group passwords must be unique") end
end
